mapper.select:
SELECT ,jso.office_name AS company, pa.position_name AS department, pl.prod_line_name AS prodLine, wg.work_group_name AS team FROM JOIN swm_person sp ON a.identity_card = sp.identity_card AND sp.STATUS = '0' AND sp.personnel_status = '1' LEFT JOIN fms_position_archive pa ON sp.department = pa.id COLLATE utf8mb4_general_ci LEFT JOIN fms_prod_line pl ON sp.prod_line = pl.id COLLATE utf8mb4_general_ci LEFT JOIN fms_work_group wg ON sp.team = wg.id COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office jso ON sp.company = jso.office_code COLLATE utf8mb4_general_ci
and a.`status` = '0'
AND a.employee_id = #{employeeId}
AND a.employee_name LIKE concat('%', #{employeeName}, '%')
AND DATE(a.attendance_date) = DATE(#{attendanceDate})
AND DATE(a.attendance_date) BETWEEN DATE(#{beginAttendanceDate}) AND DATE(#{endAttendanceDate})
AND a.work_time_range LIKE concat('%', #{workTimeRange}, '%')
AND sp.company = #{company}
AND sp.department = #{department}
AND sp.prod_line = #{prodLine}
AND sp.team = #{team}
AND #{random} = #{random}
ORDER BY a.clock_in_time IS NULL ASC, a.clock_in_time ASC
ORDER BY a.clock_in_time DESC
ORDER BY a.clock_out_time IS NULL ASC, a.clock_out_time ASC
ORDER BY a.clock_out_time DESC
ORDER BY a.effective_work_hours = 0, a.effective_work_hours ASC
ORDER BY a.effective_work_hours DESC
ORDER BY a.idle_hours = 0, a.idle_hours ASC
ORDER BY a.idle_hours DESC
group by sp.identity_card ORDER BY ${page.orderBy}
group by a.identity_card ORDER BY CASE WHEN a.clock_in_time IS NOT NULL OR a.clock_out_time IS NOT NULL OR a.effective_work_hours > 0 OR a.idle_hours > 0 THEN 0 ELSE 1 END ASC, a.attendance_date DESC, a.update_date DESC, a.id DESC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.identity_card AS "identityCard", a.person_type AS "personType", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_in_date AS "clockInDate", a.noon_end_time AS "noonEndTime", a.noon_end_date AS "noonEndDate", a.after_start_time AS "afterStartTime", a.after_start_date AS "afterStartDate", a.clock_out_time AS "clockOutTime", a.clock_out_date AS "clockOutDate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.effective_work_hours AS "effectiveWorkHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.attendance_normal AS "attendanceNormal" FROM swm_daily_attendance a
a.employee_id = #{employeeId} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.identity_card AS "identityCard", a.person_type AS "personType", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_in_date AS "clockInDate", a.noon_end_time AS "noonEndTime", a.noon_end_date AS "noonEndDate", a.after_start_time AS "afterStartTime", a.after_start_date AS "afterStartDate", a.clock_out_time AS "clockOutTime", a.clock_out_date AS "clockOutDate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.effective_work_hours AS "effectiveWorkHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_daily_attendance a
a.employee_name = #{employeeName} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT sda.employee_id AS employee_id, sda.identity_card AS identity_card, DATE_FORMAT(sda.attendance_date, '%Y-%m') AS monthly, sda.employee_name AS employee_name, sp.phone_number AS phone_number, fwg.work_group_name AS team, sp.job_type AS job_type, SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END) AS attendance_date_total, CONCAT(ROUND(SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END) * 100 / (DATEDIFF(#{endDate}, #{startDate}) + 1), 2),'%') AS attendance_rate, SUM(CASE WHEN sda.attendance_normal = 0 THEN 1 ELSE 0 END) AS valid_attendance_total, SUM(sda.actual_hours) AS actual_hours_total, SUM(sda.idle_hours) AS idle_hours_total FROM swm_daily_attendance sda LEFT JOIN swm_person sp ON sp.identity_card = sda.identity_card AND sp.NAME = sda.employee_name LEFT JOIN fms_work_group fwg ON sp.team = fwg.id COLLATE utf8mb4_general_ci WHERE sp.personnel_status = '1' AND sp.STATUS = '0' AND sda.attendance_date BETWEEN #{startDate} AND #{endDate}
AND sp.team = #{team}
AND sda.employee_name LIKE concat('%', #{employeeName}, '%')
GROUP BY sda.employee_id, sda.employee_name LIMIT #{pageNum}, #{pageSize}

SELECT COUNT(*) FROM ( SELECT DISTINCT sda.employee_id FROM swm_daily_attendance sda LEFT JOIN swm_person sp ON sp.identity_card = sda.identity_card AND sp.name = sda.employee_name LEFT JOIN fms_work_group fwg ON sp.team = fwg.id COLLATE utf8mb4_general_ci WHERE sp.personnel_status = '1' AND sp.status = '0' AND sda.attendance_date BETWEEN #{startDate} AND #{endDate}
AND sp.team = #{team}
AND sda.employee_name LIKE concat('%', #{employeeName}, '%')
GROUP BY sda.employee_id ) AS t

SELECT
    COUNT(1) as count
from
    swm_daily_attendance a
    left JOIN swm_person b on a.employee_id = b.id
WHERE
    b.job_type is NOT null and b.job_type != ''
  and a.attendance_date = #{date}
  and b.company = #{companyName}
  and b.department = #{workshopName}
  and b.prod_line = #{lineName}
  and b.team = #{teamName}
  and a.clock_in_time is NOT null
  AND b.personnel_status = '1' and b.status = '0'

select * from swm_daily_attendance where attendance_date = #{date}
                                     and clock_in_date is null
                                    and #{random} = #{random}

SELECT * FROM swm_daily_attendance WHERE identity_card IN
#{card}
and attendance_date = #{nowDate}

SELECT sda.employee_id as employee_id, sda.identity_card as identity_card, sda.employee_name as employee_name, sp.phone_number as phone_number, fwg.work_group_name as team, sp.job_type as job_type, SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END) as attendanceDay, SUM(CASE WHEN sda.attendance_normal = 0 THEN 1 ELSE 0 END) as validAttendanceDays, SUM(sda.actual_hours) as actualHours, SUM(sda.idle_hours) as idleHours FROM swm_daily_attendance sda LEFT JOIN swm_person sp ON sp.identity_card = sda.identity_card and sp.name= sda.employee_name LEFT JOIN fms_work_group fwg on sp.team = fwg.id COLLATE utf8mb4_general_ci
sp.personnel_status = '1' and sp.status = '0' and sda.attendance_date between #{startDate} and #{endDate}
AND sp.team = #{team}
AND sda.employee_name LIKE concat('%', #{employeeName}, '%')
AND sp.person_type = #{personType}
GROUP BY sda.employee_name
